import { pgSchema, text, uuid } from 'drizzle-orm/pg-core';

// The Shared context's own Postgres schema (ADR 0005). Change it, then run
// `pnpm --filter @varda/shared db:generate` and commit the new migration.
export const shared = pgSchema('shared');

export const persons = shared.table('persons', {
  // UUIDv7 from the ids adapter, never generated by the database (ADR 0006).
  id: uuid('id').primaryKey(),
  name: text('name').notNull(),
  // The login account's ID, by identity only: no foreign key across schemas (ADR 0005).
  // Exactly one person per login account.
  loginAccount: text('login_account').notNull().unique(),
});
